#!/usr/bin/env python3
"""Rebuild both checked-in examples in isolation and compare generated bytes."""
import argparse
import json
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile

from release_common import ROOT, IGNORED_DIRS


def check_examples(root):
    original = Path(root).resolve() / 'knowledge-to-plan'
    with tempfile.TemporaryDirectory(prefix='ktp-examples-') as temporary:
        copied = Path(temporary) / 'knowledge-to-plan'
        shutil.copytree(original, copied, ignore=shutil.ignore_patterns(*IGNORED_DIRS, '*.pyc', '.DS_Store'))
        commands = [
            [sys.executable, str(copied / 'scripts' / 'build_baseline.py')],
            [sys.executable, str(copied / 'scripts' / 'build_learning_site.py'),
             '--plan', str(copied / 'assets' / 'stem-example' / 'plan.json'),
             '--output', str(copied / 'assets' / 'stem-example'), '--overwrite']]
        for command in commands:
            result = subprocess.run(command, capture_output=True, text=True, encoding='utf-8')
            if result.returncode:
                raise ValueError('Example rebuild failed:\n' + result.stdout + result.stderr)
        compared = []
        for example in ('baseline', 'stem-example'):
            for name in ('index.html', 'plan.json'):
                relative = Path('assets') / example / name
                if (original / relative).read_bytes() != (copied / relative).read_bytes():
                    raise ValueError('Checked-in example is stale: knowledge-to-plan/' + relative.as_posix())
                compared.append(relative.as_posix())
    return compared


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', type=Path, default=ROOT)
    args = parser.parse_args()
    try:
        files = check_examples(args.root)
    except (OSError, ValueError) as error:
        print('Example verification failed: ' + str(error), file=sys.stderr)
        return 1
    print(json.dumps({'examples_verified': True, 'files': files}))
    return 0


if __name__ == '__main__':
    sys.exit(main())
